"""Reference-Locked 3D Scene Builder - builds tools/reflock/reflock.html from the proven kit game page (tools/kit05/kitgame.html,
left UNCHANGED) by exact, checked text patches. The result is a PHYSICAL scene:
  * plain perspective camera, no camera-relative depth curve (uZ2 = 1e6 -> identity), no camera-distance texture switching
  * own approved pixels only on the near sections, handed over to the shared section tile at a WORLD-fixed axial range
  * real 3D gold paddles (lifters), real 3D coins, real 3D foam domes, real 3D iridescent bubbles (instanced meshes)
  * a physical tunnel mouth (bulkhead + approach duct) and a physical exit (exit ring + bright exit room) instead of a glow sprite
    and a screen overlay; the exit light brightens the last sections in world space
  * QA hooks: ?sentinel=1 (pure green background: any visible hole in the geometry shows green), window.sceneAudit(), ?s0=
Every patch must match exactly once, otherwise the build stops (a changed kit page can never be patched silently).
  python3 -I tools/reflock/make_page.py            -> tools/reflock/reflock.html
"""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); REPO = os.path.abspath(os.path.join(HERE, '..', '..'))
src = open(os.path.join(REPO, 'tools/kit05/kitgame.html'), encoding='utf8').read()
P = []
def patch(old, new, count=1):
    global src
    n = src.count(old)
    if n != count: sys.exit(f'PATCH FAILED ({n} matches, expected {count}): {old[:90]!r}')
    src = src.replace(old, new); P.append(old[:60])

patch('<title>Screen 05 tunnel kit game test</title>', '<title>Rainbow reference-locked physical scene</title>')
patch('// Round 33 KIT TEST (experimental, not the game)', '// REFERENCE-LOCKED PHYSICAL SCENE (tools/reflock, generated by make_page.py from tools/kit05/kitgame.html; edit make_page.py, not this file).\n'
      '// Physical world-space geometry + world-anchored textures baked from the approved picture, plain perspective camera.\n// (kit page header follows) Round 33 KIT TEST (experimental, not the game)')
patch("const q = new URLSearchParams(location.search);",
      "const q = new URLSearchParams(location.search);\n"
      "// physical defaults: reference-video movement, live world-space river, no screen-overlap coin shrinking, no camera-dependent switches\n"
      "for (const [k, v] of [['move', '1'], ['w37', '1'], ['noclutter', '1'], ['ownoff', '0']]) if (!q.has(k)) q.set(k, v);\n"
      "const SC = await (await fetch('screen.json')).json(), PH = await (await fetch('phys.json')).json();")
patch("const OWNFADE = PROJ ? [-2, -1] : (K.own?.fade ?? [0.42, 0.62]);",
      "const OWNFADE = SC.own.blend_t;   // WORLD axial range of the own-pixel -> shared-tile hand-over (never camera-dependent)")
patch("const ringT = (k) => K.Z2 + (k - 2) * K.S;", "const ringT = (k) => (k < PH.ring_ts.length ? PH.ring_ts[k] : PH.ring_ts[PH.ring_ts.length - 1] + (k - PH.ring_ts.length + 1) * PH.S);   // world-fixed physical rings (phys.json)\nconst secLen = (k) => ringT(k + 1) - ringT(k);")
patch("uZ2: { value: K.Z2 }", "uZ2: { value: 1e6 }, uGlowC: { value: new THREE.Color(1.0, 0.93, 0.80) }, uGlowT: { value: new THREE.Vector3(PH.ring_ts[PH.exit_ring] + SC.exit_glow[0], PH.ring_ts[PH.exit_ring] + SC.exit_glow[1], SC.exit_glow[2]) }")
patch("""'#include <common>\\nuniform float uBias;' + (own ? '\\nuniform sampler2D uOwn; uniform vec2 uVr; uniform vec2 uFade; uniform float uOwnOff; varying float vKitT; varying float vKitD;' : ''));""",
      """'#include <common>\\nuniform float uBias; uniform vec3 uGlowC; uniform vec3 uGlowT; varying float vKitT; varying float vKitD;' + (own ? '\\nuniform sampler2D uOwn; uniform vec2 uVr; uniform vec2 uFade; uniform float uOwnOff; uniform float uSecR;' : ''))
      .replace('#include <alphamap_fragment>', '{ float kGl = uGlowT.z * pow(smoothstep(uGlowT.x, uGlowT.y, vKitT), 1.6); diffuseColor.rgb = mix(diffuseColor.rgb, uGlowC, kGl); }\\n#include <alphamap_fragment>');""")
patch("uFade: { value: new THREE.Vector2(...OWNFADE) } } : {};", "uFade: { value: new THREE.Vector2(...OWNFADE) }, uSecR: { value: own.secR ?? 1 } } : {};")
patch("1.0 - (uVr.x + (1.0 - vMapUv.y) * (uVr.y - uVr.x))", "1.0 - (uVr.x + (1.0 - vMapUv.y) * uSecR * (uVr.y - uVr.x))")   # own rows span the real section length
patch("float kF = smoothstep(uFade.x, uFade.y, vKitD / max(vKitT, 1e-3)) * (1.0 - uOwnOff);",
      "float kF = 1.0 - smoothstep(uFade.x, uFade.y, vKitT);   // physical: own pixels on the near sections, world-fixed hand-over")
patch("uniform float uFlowOn; varying float vKitT; varying float vKitD;", "uniform float uFlowOn;")
patch("'uniform float uBias; varying float vKitT; varying float vKitD;'", "'uniform float uBias;'")
patch("tex('wall.png'), tex('ring.png')", "tex('wall_tile.png'), tex('ring_tile.png')")
patch("const ownOf = (kind, atlas, k) => { const r = K.own?.[kind]?.rows?.[k]; return r && !q.get('noown') ? { tex: atlas, vr: [r[0] / K.own[kind].h, r[1] / K.own[kind].h] } : null; };",
      "const ownOf = (kind, atlas, k) => { const r = PH.own?.[kind]?.rows?.[k]; return r && !q.get('noown') && ringT(k) < OWNFADE[1] ? { tex: atlas, vr: [r[0] / PH.own[kind].h, r[1] / PH.own[kind].h], secR: kind === 'wall' ? PH.S / secLen(k) : 1 } : null; };")
# live river: no camera-distance pattern (near-camera arcs) and no camera-distance glow; the exit light is world-space (uGlow*)
patch("float near = (1.0 - smoothstep(0.9, 2.6, kZ)) * (1.0 - simple);", "float near = 0.0;   // physical: no camera-relative arcs")
patch("col = mix(col, w37c(200.0, 235.0, 255.0), 0.28 * smoothstep(5.0, 16.0, kZ) * exp(-u * u * 1.5));", "// physical: the far glow comes from the real exit light (uGlow*), not from the camera distance")
# the painted near water, world-anchored on the physical river (river_own.png), streaming a little; world-fixed hand-over to the live river
patch("uniform float uW37; uniform vec4 uW37A; uniform float uW37T;", "uniform float uW37; uniform vec4 uW37A; uniform float uW37T; uniform sampler2D uROT; uniform vec3 uRO; uniform vec2 uROB;")
patch("if (uW37 > 0.5) { kRib = w37(kT, kLat, kZ); kWP = 0.0; }",
      """if (uW37 > 0.5) { kRib = w37(kT, kLat, kZ); kWP = 0.0;
          if (uRO.z > 0.0 && vMapUv.x >= 0.0 && vMapUv.x <= 1.0) { float rph = fract(uFlow * 1.3), rl = uFlowL * uFlowOn;
            vec4 ro1 = texture(uROT, vec2(vMapUv.x, (kT + rph * rl - uRO.x) / (uRO.y - uRO.x)), uBias), ro2 = texture(uROT, vec2(vMapUv.x, (kT + fract(rph + 0.5) * rl - uRO.x) / (uRO.y - uRO.x)), uBias);
            vec4 ro = mix(ro2, ro1, 1.0 - abs(1.0 - 2.0 * rph)); float rw = uRO.z * ro.a * (1.0 - smoothstep(uROB.x, uROB.y, kT));
            kRib.rgb = mix(kRib.rgb, ro.rgb, rw); } }""")
patch("uW37: { value: W37 },", "uW37: { value: W37 }, uROT: { value: null }, uRO: { value: new THREE.Vector3(SC.river_own.t0, SC.river_own.t1, q.get('rown') === '0' ? 0 : 1) }, uROB: { value: new THREE.Vector2(...SC.river_own.blend_t) },")
patch("const NSEC = +(q.get('nsec') ?? 30), KMIN = -1;", "const NSEC = PH.exit_ring, KMIN = SC.tunnel.entry_ring;   // physical tunnel: mouth ring .. exit ring")
# wall sections take their real (possibly longer) length; the shared tile repeats at its own world period S (never stretched)
patch("scene.add(new THREE.Mesh(grid(160, 24, (a, b) => [P(t0 + b * K.S, lerp(K.TH0, K.TH1, a), K.RT), a, 1 - b]),", "scene.add(new THREE.Mesh(grid(160, Math.ceil(24 * secLen(k) / K.S), (a, b) => [P(t0 + b * secLen(k), lerp(K.TH0, K.TH1, a), K.RT), a, 1 - b * secLen(k) / K.S]),")

# ---------------- physical pieces after the tunnel sections ----------------
PHYS_BLOCK = r"""
// ================= REFERENCE-LOCKED PHYSICAL PIECES (world space; nothing follows the camera) =================
wallTex.wrapT = THREE.RepeatWrapping; wallTex.needsUpdate = true;
FLOW.uROT.value = await tex('river_own.png');
const T_EXIT = ringT(NSEC), RA = SC.tunnel.approach.radius, T_APP = SC.tunnel.approach.t0;
const physGroup = new THREE.Group(); physGroup.name = 'physical'; scene.add(physGroup);
// exit ring (front face + inner face, shared ring tile)
physGroup.add(new THREE.Mesh(grid(160, 8, (a, b) => { const th = lerp(K.TH0, K.TH1, a);
  if (b <= 0.5) { const f = b / 0.5; return [P(T_EXIT, th, K.RT - (K.RT - K.RING_IN) * f), a, 1 - b]; }
  const f = (b - 0.5) / 0.5; return [P(T_EXIT + f * K.RING_W, th, K.RING_IN), a, 1 - b]; }), ringMat));
// tunnel mouth: the bulkhead around ring 0 and the wider approach duct the river arrives through
const TH_A0 = -22 * DEG0, TH_A1 = 202 * DEG0;
physGroup.add(new THREE.Mesh(grid(120, 10, (a, b) => [P(ringT(KMIN), lerp(TH_A0, TH_A1, a), lerp(K.RT, RA, b)), a, b * 0.6]), wallMat));
physGroup.add(new THREE.Mesh(grid(120, 60, (a, b) => { const t = lerp(T_APP, ringT(KMIN), b); return [P(t, lerp(TH_A0, TH_A1, a), RA), a, (t - ringT(KMIN)) / K.S]; }), wallMat));
// approach water and exit-room water: the same live river material (world-space), just below the tunnel water so they never fight
const waterGrid = (t0, t1, hw, nv) => new THREE.Mesh(grid(60, nv, (a, b) => { const t = lerp(t0, t1, b), l = lerp(-hw, hw, a);
  return [A0.clone().addScaledVector(A, t).addScaledVector(RR, l).addScaledVector(NUP, -K.HW - 0.002), (l + K.water.HWD) / (2 * K.water.HWD), b]; }), riverMat);
physGroup.add(waterGrid(T_APP, ringT(KMIN) + 0.05, RA - 0.05, 80));
const ROOM = SC.tunnel.exit_room, roomC = A0.clone().addScaledVector(A, T_EXIT + ROOM.depth - 1.0);
physGroup.add(waterGrid(T_EXIT - 0.3, T_EXIT + ROOM.depth - 1.0 + ROOM.radius * 0.95, ROOM.radius * 0.97, 120));
// exit room: the bright chamber the tunnel opens into (its light is the far glow of the approved picture)
{ const m = new THREE.ShaderMaterial({ side: THREE.BackSide, toneMapped: false, uniforms: { uC: { value: roomC }, uA: { value: A.clone() }, uU: { value: NUP.clone() } },
    vertexShader: 'varying vec3 vD; uniform vec3 uC; void main(){ vec4 wp = modelMatrix * vec4(position, 1.0); vD = normalize(wp.xyz - uC); gl_Position = projectionMatrix * viewMatrix * wp; }',
    fragmentShader: `varying vec3 vD; uniform vec3 uA; uniform vec3 uU; void main(){ float f = dot(vD, uA), u = dot(vD, uU);
      // the painting's far light: a small white-hot centre straight down the tunnel, warm gold around it, peach-pink toward the sides
      vec3 core = vec3(1.0, 0.98, 0.90), gold = vec3(1.0, 0.74, 0.36), warm = vec3(1.0, 0.84, 0.62), pink = vec3(0.96, 0.62, 0.84);
      vec3 c = mix(pink, warm, smoothstep(-0.7, 0.4, f)); c = mix(c, gold, smoothstep(0.8, 0.97, f)); c = mix(c, core, smoothstep(0.985, 0.998, f));
      c = mix(c, core, 0.2 * smoothstep(0.3, 1.0, u));
      gl_FragColor = vec4(c, 1.0); }` });
  const room = new THREE.Mesh(new THREE.SphereGeometry(ROOM.radius, 48, 32), m); room.position.copy(roomC); room.name = 'exit_room'; physGroup.add(room); }
// real 3D gold paddles (the painted lifters): the painted placement on the sections the picture shows, then repeating; own painted
// pixels on the paddles the picture shows (paddle_own.png column per paddle), the medium painted paddle's pixels on the later ones
{ const PD = SC.paddles, pmap = PH.own.paddle.map, NP = PH.own.paddle.n;
  const ptex = await tex('paddle_own.png'); const pmat = kitMat(ptex);
  const place = (k) => { const o = PD.by_section?.[String(k)] ?? {}; return [o.t_off ?? PD.t_off, o.theta_rad ?? PD.theta_rad]; };
  for (let k = PD.k0; k < NSEC; k++) { const [toff, ths] = place(k);
    ths.forEach((thc, j) => { const col = (pmap[`${k}_${j}`] ?? pmap[`2_${j}`] ?? [0])[0], t1 = ringT(k) + toff * secLen(k), dth = PD.half_width_rad;
      const mesh = new THREE.Mesh(grid(16, 10, (a, b) => { const th = thc + (a - 0.5) * 2 * dth, ext = Math.sqrt(Math.max(0, 1 - (2 * a - 1) ** 2)), rIn = K.RT - (K.RT - PD.r_inner) * Math.sqrt(ext);
        if (b < 0.7) { const f = b / 0.7; return [P(t1 + PD.length * (1 - f), th, rIn), (col + a) / NP, 1 - b]; }
        const f = (b - 0.7) / 0.3; return [P(t1, th, lerp(rIn, K.RT, f)), (col + a) / NP, 1 - b]; }), pmat);
      mesh.name = `paddle_${k}_${j}`; physGroup.add(mesh); }); } }
"""
