# ---------------- foam domes + bubbles: real 3D instanced meshes instead of camera-facing billboards ----------------
lines = src.split('\n'); i0 = next(i for i, l in enumerate(lines) if l == 'if (PUFFS) {')
i1 = next(i for i in range(i0, len(lines)) if lines[i].startswith('  window.__ambient = '))
assert lines[i1 + 1] == '}', lines[i1 + 1]
FOAM = r"""if (PUFFS) {
  // REFERENCE-LOCKED: real 3D foam domes (instanced flattened spheres standing in the water along the river's winding banks) and real
  // 3D iridescent soap bubbles (instanced spheres), world-anchored, lit from the exit light ahead; no billboards, no camera-distance fades
  const rp = (() => { let x = 777; return () => ((x = (x * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff); })();
  const HWD = K.water.HWD, T_E = ringT(NSEC), T_A = SC.tunnel.approach.t0, L = [];
  for (const [t, lat, w] of (PH.foam_painted ?? [])) L.push([t, lat, w]);   // the painting's own foam, as real domes where it lies
  const T_PF = SC.river_own.blend_t[1];
  for (const side of [1, -1]) for (let t = T_A + 0.3; t < T_E + 5.5; t += 0.06 + rp() * 0.05) {
    if (t > ringT(KMIN) && t < T_PF && (PH.foam_painted ?? []).length) { t = T_PF; continue; }
    const RW37 = FLOW.uW37A.value.x, e37 = FLOW.uW37A.value.z * riverC(t) + side * RW37, wide = t < ringT(KMIN) - 0.05 || t > T_E + 0.2;
    const lim = wide ? SC.tunnel.approach.radius - 0.15 : HWD - 0.04, nr = wide ? 5 : (HWD - Math.abs(e37) > 0.14 ? 3 : 2);
    for (let r = 0; r < nr; r++) { const w = (0.07 + rp() * 0.06) * (r ? 0.85 : 1), lat = THREE.MathUtils.clamp(e37 + side * (0.03 + r * 0.075 + rp() * 0.03), -lim, lim);
      if ((lat - e37) * side > 0.01) L.push([t + rp() * 0.03, lat, w]); }
  }
  const fGeo = new THREE.IcosahedronGeometry(0.5, 2);
  const fMat = new THREE.ShaderMaterial({ toneMapped: false, uniforms: { uL: { value: NUP.clone().multiplyScalar(0.75).addScaledVector(A, 0.6).addScaledVector(RR, -0.25).normalize() }, uAx: { value: A.clone() }, uA0: { value: A0.clone() }, uGlowT: REMAP.uGlowT },
    vertexShader: `varying vec3 vN; varying float vT; uniform vec3 uAx; uniform vec3 uA0; void main(){ vec4 wp = modelMatrix * instanceMatrix * vec4(position, 1.0);
      vN = normalize(mat3(modelMatrix) * mat3(instanceMatrix) * normal); vT = dot(wp.xyz - uA0, uAx); gl_Position = projectionMatrix * viewMatrix * wp; }`,
    fragmentShader: `varying vec3 vN; varying float vT; uniform vec3 uL; uniform vec3 uGlowT; vec3 c3(float r, float g, float b){ return vec3(r, g, b) / 255.0; }
      void main(){ float d = dot(normalize(vN), uL), lit = clamp(0.5 + 0.55 * d, 0.0, 1.0);
        vec3 col = lit < 0.5 ? mix(c3(132.0, 116.0, 214.0), c3(196.0, 190.0, 242.0), lit / 0.5) : mix(c3(196.0, 190.0, 242.0), c3(253.0, 251.0, 255.0), (lit - 0.5) / 0.5);
        col = mix(col, vec3(1.0, 0.96, 0.9), uGlowT.z * pow(smoothstep(uGlowT.x, uGlowT.y, vT), 1.6)); gl_FragColor = vec4(col, 1.0); }` });
  const foam = new THREE.InstancedMesh(fGeo, fMat, L.length), mI = new THREE.Matrix4(), bas = new THREE.Matrix4().makeBasis(RR, NUP, A), qI = new THREE.Quaternion().setFromRotationMatrix(bas), pI = new THREE.Vector3(), sI = new THREE.Vector3();
  L.forEach(([t, lat, w], i) => { pI.copy(A0).addScaledVector(A, t).addScaledVector(RR, lat).addScaledVector(NUP, -K.HW + w * 0.12); sI.set(w, w * 0.62, w * 1.15); foam.setMatrixAt(i, mI.compose(pI, qI, sI)); });
  foam.name = 'foam_domes'; foam.frustumCulled = false; scene.add(foam);
  const B = []; for (let t = T_A + 1; t < T_E + 5; t += 0.11 + rp() * 0.14) { const side = rp() < 0.5 ? -1 : 1, inT = t > ringT(KMIN) && t < T_E;
    B.push([t, side * (0.3 + rp() * (inT ? 0.36 : 1.1)), 0.03 + rp() * rp() * (inT ? 0.5 : 0.9), 0.022 + rp() * rp() * 0.06, rp() * 6.28]); }
  const bGeo = new THREE.SphereGeometry(1, 20, 14); bGeo.setAttribute('aPh', new THREE.InstancedBufferAttribute(new Float32Array(B.map((b) => b[4])), 1));
  const bm = new THREE.ShaderMaterial({ transparent: true, depthWrite: false, toneMapped: false, uniforms: { uTime: { value: 0 }, uUp: { value: NUP.clone() }, uL: fMat.uniforms.uL },
    vertexShader: `attribute float aPh; uniform float uTime; uniform vec3 uUp; varying vec3 vN; varying vec3 vW; void main(){
      vec4 wp = modelMatrix * instanceMatrix * vec4(position, 1.0); wp.xyz += uUp * 0.015 * sin(uTime * 1.3 + aPh);
      vN = normalize(mat3(modelMatrix) * mat3(instanceMatrix) * normal); vW = wp.xyz; gl_Position = projectionMatrix * viewMatrix * wp; }`,
    fragmentShader: `varying vec3 vN; varying vec3 vW; uniform vec3 uL; void main(){ vec3 N = normalize(vN), V = normalize(cameraPosition - vW);
      float f = pow(1.0 - abs(dot(N, V)), 2.2); vec3 film = 0.55 + 0.45 * cos(6.2832 * (f * 1.4 + vec3(0.0, 0.33, 0.67)));
      float sp = pow(max(dot(reflect(-V, N), uL), 0.0), 50.0);
      vec3 col = mix(vec3(0.85, 0.9, 1.0), film, 0.8) + sp; gl_FragColor = vec4(min(col, vec3(1.0)), clamp(0.07 + 0.85 * f + sp, 0.0, 0.95)); }` });
  const bubbles = new THREE.InstancedMesh(bGeo, bm, B.length);
  B.forEach(([t, lat, h, r], i) => { pI.copy(A0).addScaledVector(A, t).addScaledVector(RR, lat).addScaledVector(NUP, -K.HW + h + r); sI.setScalar(r); bubbles.setMatrixAt(i, mI.compose(pI, qI, sI)); });
  bubbles.name = 'bubbles'; bubbles.frustumCulled = false; bubbles.renderOrder = 7; scene.add(bubbles);
  window.__ambient = { puffs: L.length, bubbles: B.length, tick: (t) => { bm.uniforms.uTime.value = t; } };
}"""
lines[i0:i1 + 2] = FOAM.split('\n'); src = '\n'.join(lines); P.append('PUFFS block -> 3D foam + bubbles')

